**Example 2: Extension Registration (Startup)**

```csharp
public class Startup
{
    public void ConfigureServices(IServiceCollection services)
    {
        // Register extension infrastructure
        services.AddSingleton<IExtensionRegistry, ExtensionRegistry>();
        services.AddScoped<IExtensionExecutor, ExtensionExecutor>();

        // Register extension points
        services.AddExtensionPoint<IClaimsValidationExtension>("claims.validation");
        services.AddExtensionPoint<IPreClaimsProcessingExtension>("claims.pre-process");
        services.AddExtensionPoint<IPostClaimsProcessingExtension>("claims.post-process");
    }

    public void Configure(IApplicationBuilder app, IExtensionRegistry registry)
    {
        // Auto-discover and register extensions from loaded plugins
        var pluginHost = app.ApplicationServices.GetRequiredService<IPluginHost>();
        var extensions = pluginHost.DiscoverExtensions<IExtensionPoint>();

        foreach (var extension in extensions)
        {
            registry.RegisterExtension(extension.ExtensionPointId, extension);
        }
    }
}
```

