### Real-World Example 2: Provider Enrollment Workflow Extension

**Business Scenario**: State B has a unique provider enrollment workflow that includes additional approval steps for out-of-state providers and requires integration with their state licensing board API.

**Core Product Extension Point**:

```csharp
public interface IProviderEnrollmentExtension : IExtensionPoint<EnrollmentContext, EnrollmentStepResult>
{
    string StepName { get; }
    Task<bool> AppliesAsync(EnrollmentContext context);
}

public class EnrollmentContext
{
    public ProviderApplication Application { get; set; }
    public EnrollmentWorkflowState WorkflowState { get; set; }
    public IServiceProvider Services { get; set; }
}

public class EnrollmentStepResult
{
    public bool Success { get; set; }
    public string NextStep { get; set; }
    public List<string> Errors { get; set; }
    public Dictionary<string, object> Data { get; set; }
}
```

**State B Custom Workflow Step**:

```csharp
[Extension("provider.enrollment.custom-step")]
public class StateBOutOfStateProviderVerification : IProviderEnrollmentExtension
{
    private readonly IStateBLicensingBoardClient _licensingBoard;

    public string ExtensionPointId => "provider.enrollment.custom-step";
    public string StepName => "State B Out-of-State Verification";
    public Version InterfaceVersion => new Version(1, 0, 0);
    public int Priority => 200; // After core credential check (100)

    public async Task<bool> AppliesAsync(EnrollmentContext context)
    {
        // Only for State B, only for out-of-state providers
        return context.Application.StateId == "StateB" &&
               context.Application.ProviderState != "StateB";
    }

    public async Task<EnrollmentStepResult> ExecuteAsync(
        EnrollmentContext context,
        CancellationToken cancellationToken)
    {
        var app = context.Application;
        var errors = new List<string>();

        // Verify license with State B licensing board
        var licenseVerification = await _licensingBoard.VerifyLicenseAsync(
            app.LicenseNumber,
            app.ProviderState);

        if (!licenseVerification.IsValid)
        {
            errors.Add($"License verification failed: {licenseVerification.Reason}");
        }

        // Check for disciplinary actions
        var disciplinaryCheck = await _licensingBoard.CheckDisciplinaryActionsAsync(
            app.LicenseNumber);

        if (disciplinaryCheck.HasActions)
        {
            // Requires manual review
            return new EnrollmentStepResult
            {
                Success = true,
                NextStep = "ManualReview",
                Data = new Dictionary<string, object>
                {
                    ["DisciplinaryActions"] = disciplinaryCheck.Actions,
                    ["RequiresReviewBy"] = "State B Compliance Team"
                }
            };
        }

        return new EnrollmentStepResult
        {
            Success = !errors.Any(),
            NextStep = errors.Any() ? null : "BackgroundCheck",
            Errors = errors,
            Data = new Dictionary<string, object>
            {
                ["LicenseVerified"] = licenseVerification.IsValid,
                ["VerificationDate"] = DateTime.UtcNow
            }
        };
    }
}
```

**Core Workflow Integration**:

```csharp
public class ProviderEnrollmentService
{
    public async Task<EnrollmentResult> ProcessEnrollmentAsync(ProviderApplication application)
    {
        var context = new EnrollmentContext
        {
            Application = application,
            WorkflowState = new EnrollmentWorkflowState(),
            Services = _serviceProvider
        };

        // Core enrollment steps
        await ExecuteStep("ValidateApplication", context);
        await ExecuteStep("VerifyCredentials", context);

        // Extension point: State-specific enrollment steps
        var customSteps = await _extensionExecutor.InvokeExtensionsAsync<
            EnrollmentContext, EnrollmentStepResult>(
                "provider.enrollment.custom-step",
                context);

        foreach (var stepResult in customSteps)
        {
            if (!stepResult.Success)
            {
                return EnrollmentResult.Failed(stepResult.Errors);
            }

            // Update workflow based on extension result
            if (stepResult.NextStep != null)
            {
                await ExecuteStep(stepResult.NextStep, context);
            }
        }

        // Continue standard workflow
        return await CompleteEnrollmentAsync(context);
    }
}
```

**Benefits**:
- State B adds custom workflow steps without modifying core
- Out-of-state provider verification logic isolated
- State B can update licensing board integration independently
- Core enrollment flow remains clean and maintainable

