[Extension("claims.pre-process")]
public class StateCDemographicEnrichmentExtension : IPreClaimsProcessingExtension
{
    private readonly IDemographicDataService _demographicService;

    public string ExtensionPointId => "claims.pre-process";
    public Version InterfaceVersion => new Version(1, 0, 0);
    public int Priority => 10; // Run early

    public async Task<bool> AppliesAsync(ClaimContext context)
    {
        return context.Claim.StateId == "StateC";
    }

    public async Task<PreProcessingResult> ExecuteAsync(
        ClaimContext context,
        CancellationToken cancellationToken)
    {
        var claim = context.Claim;

        // Lookup member's county via State C data service
        var memberDemographics = await _demographicService.GetMemberDemographicsAsync(
            claim.MemberId);

        // Enrich claim with county code
        claim.CountyCode = memberDemographics.CountyCode;
        claim.DemographicZone = memberDemographics.UrbanRuralDesignation;

        return new PreProcessingResult
        {
            Success = true,
            ModifiedClaim = claim,
            ExtensionData = new Dictionary<string, object>
            {
                ["EnrichedBy"] = "StateCDemographicEnrichment",
                ["CountyCode"] = memberDemographics.CountyCode
            }
        };
    }
}
```

**Benefit**: Claim is enriched before any validation or processing logic runs, State C logic isolated.

