[Extension("claims.post-process")]
public class StateDDataWarehouseTransformation : IPostClaimsProcessingExtension
{
    private readonly IStateDDataWarehouseClient _dataWarehouse;

    public string ExtensionPointId => "claims.post-process";
    public Version InterfaceVersion => new Version(1, 0, 0);
    public int Priority => 50;

    public async Task<bool> AppliesAsync(ClaimResultContext context)
    {
        return context.Claim.StateId == "StateD";
    }

    public async Task<TransformationResult> ExecuteAsync(
        ClaimResultContext context,
        CancellationToken cancellationToken)
    {
        // Transform to State D format
        var stateDFormat = new StateDClaimRecord
        {
            ClaimIdentifier = context.Claim.ClaimId,
            AdjudicationStatus = MapToStateDStatus(context.AdjudicationResult.Status),
            PaymentAmount = context.AdjudicationResult.PaidAmount,
            DenialReason = context.AdjudicationResult.DenialCode,
            ProcessedTimestamp = DateTime.UtcNow,
            // State D specific fields
            FiscalYear = GetStateDFiscalYear(context.Claim.ServiceDate),
            ProgramCode = GetStateDProgramCode(context.Claim.ProgramType)
        };

        // Send to State D data warehouse (async, fire-and-forget)
        await _dataWarehouse.PostClaimRecordAsync(stateDFormat);

        return new TransformationResult
        {
            Success = true,
            Message = "Claim record sent to State D data warehouse"
        };
    }
}
```

**Benefit**: Core system produces standard output, State D transformation handled by extension without affecting core logic.

