#### Scenario 3: Validation Rule Extension

**Use Case**: State E has specialized NICU (Neonatal Intensive Care Unit) claims validation that requires checking infant age, admission criteria, and length of stay limits.

**Extension Point Definition**:

```csharp
public interface IClaimsValidationExtension : IExtensionPoint<ClaimValidationContext, ValidationResult>
{
    Task<bool> AppliesAsync(ClaimValidationContext context);
}
```

**State E Implementation**:

```csharp
[Extension("claims.validation")]
public class StateENICUValidationExtension : IClaimsValidationExtension
{
    private readonly IStateERulesEngine _rulesEngine;

    public string ExtensionPointId => "claims.validation";
    public Version InterfaceVersion => new Version(1, 0, 0);
    public int Priority => 120;

    public async Task<bool> AppliesAsync(ClaimValidationContext context)
    {
        // Only applies to State E NICU claims
        return context.Claim.StateId == "StateE" &&
               context.Claim.ServiceType == "NICU";
    }

    public async Task<ValidationResult> ExecuteAsync(
        ClaimValidationContext context,
        CancellationToken cancellationToken)
    {
        var claim = context.Claim;
        var errors = new List<ValidationError>();

        // State E NICU Rule #1: Infant must be under 1 year
        var member = await GetMemberAsync(claim.MemberId);
        var ageAtService = claim.ServiceDate - member.DateOfBirth;
        if (ageAtService.TotalDays > 365)
        {
            errors.Add(new ValidationError
            {
                Code = "STATEE-NICU-001",
                Message = "NICU services are only covered for infants under 1 year",
                Field = "MemberId"
            });
        }

        // State E NICU Rule #2: Must meet birth weight or gestational criteria
        var admissionRecord = await _rulesEngine.GetAdmissionRecordAsync(claim.AdmissionId);
        if (admissionRecord.BirthWeight >= 2500 && admissionRecord.GestationalAge >= 37)
        {
            errors.Add(new ValidationError
            {
                Code = "STATEE-NICU-002",
                Message = "NICU admission does not meet State E criteria",
                Severity = "Error"
            });
        }

        // State E NICU Rule #3: Length of stay limits
        var lengthOfStay = claim.DischargeDate - claim.AdmissionDate;
        var maxStay = await _rulesEngine.GetMaxNICUStayAsync(admissionRecord.SeverityLevel);
        if (lengthOfStay.TotalDays > maxStay)
        {
            errors.Add(new ValidationError
            {
                Code = "STATEE-NICU-003",
                Message = $"NICU stay exceeds State E limit of {maxStay} days for severity level {admissionRecord.SeverityLevel}",
                Field = "DischargeDate"
            });
        }

        return new ValidationResult
        {
            Success = !errors.Any(),
            Errors = errors,
            IsCritical = errors.Any(e => e.Severity == "Error")
        };
    }
}
```

**Benefit**: Highly specialized State E NICU validation logic isolated from core product, can be updated by State E team independently.
